int[] rollNums = new int[3];
int x = 101;
for (int i = 0; i < rollNums.length; i++) {
    rollNums[i] = x;
    x++;
}
System.out.println(rollNums.length + " " + rollNums[2] + " " + x);

int[][] marks = new int[3][];
marks[0] = new int[1];
marks[1] = new int[2];
marks[2] = new int[3];

int total = 0;
for (int row = 0; row < marks.length; row++) {
    for (int col = 0; col < marks[row].length; col++) {
        marks[row][col] = row + col;
        total += marks[row][col];
    }
}
System.out.println(marks.length + " " + marks[2].length + " " + total);
